package com.franco.desco.application.resourceprogram.service;import com.franco.desco.application.resourceprogram.*;import com.franco.desco.application.resourceprogram.port.in.ResourceProgramUseCase;import com.franco.desco.application.resourceprogram.port.out.ResourceProgramPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.resourceprogram.ResourceProgramModels;
public final class ResourceProgramApplicationService implements ResourceProgramUseCase{private final ResourceProgramPersistencePort p;public ResourceProgramApplicationService(ResourceProgramPersistencePort p){this.p=p;}public AppResult<PageResult<ResourceProgramModels.Summary>>list(ResourceProgramCommands.ListResources c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"RECURSOS_LISTADOS","RECURSOS_NO_LISTADOS",AppStatus.BAD_REQUEST);}public AppResult<ResourceProgramModels.Detail>get(ResourceProgramCommands.Get c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.get(c,i,m),"RECURSO_CONSULTADO","RECURSO_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<ResourceProgramModels.Availability>availability(SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.availability(i,m),"RECURSOS_DISPONIBLES","DISPONIBILIDAD_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<Long>program(ResourceProgramCommands.Program c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.program(c,i,m),"RECURSO_PROGRAMADO","RECURSO_NO_PROGRAMADO");}public AppResult<Void>update(ResourceProgramCommands.Update c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.update(c,i,m),"RECURSO_ACTUALIZADO","RECURSO_NO_ACTUALIZADO",AppStatus.BAD_REQUEST);}public AppResult<Void>assign(ResourceProgramCommands.Assign c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.assign(c,i,m),"RECURSO_ASIGNADO","RECURSO_NO_ASIGNADO",AppStatus.BAD_REQUEST);}public AppResult<Void>returnResource(ResourceProgramCommands.ReturnResource c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.returnResource(c,i,m),"RECURSO_DEVUELTO","RECURSO_NO_DEVUELTO",AppStatus.BAD_REQUEST);}public AppResult<Void>cancel(ResourceProgramCommands.Cancel c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.cancel(c,i,m),"RECURSO_CANCELADO","RECURSO_NO_CANCELADO",AppStatus.BAD_REQUEST);}}
